sp_widget.client_script:
api.controller = function() {
    var c = this;
    c.activeIndex = -1;

    c.toggle = function(index) {
        c.activeIndex = c.activeIndex === index ? -1 : index;
    };

    c.isActive = function(index) {
        return c.activeIndex === index;
    };
};

sp_widget.css:
.help-widget {
  max-width: 800px;
  margin: 0 auto;
}

.help-header {
  background-color: $brand-primary;
  color: #fff;
  border: none;
}

.help-header .panel-title {
  font-weight: 600;
  color: #fff;
}

.faq-panel {
  border: 1px solid #e0e0e0;
  margin-bottom: 5px;
}

.faq-heading {
  cursor: pointer;
  padding: 12px 15px;
  transition: background-color 0.2s ease;
}

.faq-heading:hover {
  background-color: #f5f5f5;
}

.faq-title {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
}

.faq-title .fa {
  margin-right: 8px;
  color: #999;
  width: 14px;
}

.faq-answer {
  color: #555;
  line-height: 1.6;
  font-size: 14px;
}

sp_widget.script:
(function() {
    data.faqs = [
        {
            question: 'How do I report a warehouse exception?',
            answer: 'Click "Report Exception" in the navigation menu. Fill in the required fields: Short Description, Exception Type, and Severity. Optionally add a detailed description and location. Click Submit to create the exception record.'
        },
        {
            question: 'How do I track my exceptions?',
            answer: 'Your dashboard shows all exceptions you have reported (for staff) or been assigned (for technicians). Use the KPI cards at the top for a quick overview, and the table below for detailed records. Click "View" on any record to see its full details.'
        },
        {
            question: 'What do the status values mean?',
            answer: 'New: Just reported, awaiting assignment. Assigned: A technician has been assigned. In Progress: The technician is actively working on it. Pending: Waiting for additional information or action. Resolved: The issue has been fixed. Closed: The exception is finalized and closed.'
        },
        {
            question: 'How do I add comments or work notes?',
            answer: 'Open the exception detail page by clicking "View" on any record. Scroll down to the Work Notes section. Type your note and click "Add Note". All users with access can add work notes.'
        },
        {
            question: 'Who handles my exception?',
            answer: 'Exceptions are assigned to technicians by supervisors. Once assigned, the technician can update the status and add resolution notes. You will be notified when your exception status changes.'
        },
        {
            question: 'What are AI Suggestions?',
            answer: 'The system uses AI to automatically suggest the exception type, severity, and routing based on the description you provide. These suggestions appear on the detail page and help supervisors make faster assignment decisions.'
        }
    ];
})();
